{"command":"$base = 'http://127.0.0.1:12463/mcp'
try {
  $get = Invoke-WebRequest -Uri $base -Method Get -UseBasicParsing -ErrorAction Stop
  "GET_STATUS=$($get.StatusCode)"
} catch {
  if ($_.Exception.Response) { "GET_STATUS=$([int]$_.Exception.Response.StatusCode)" } else { "GET_ERROR=$($_.Exception.Message)" }
}
$initBody = @{ jsonrpc='2.0'; id=1; method='initialize'; params=@{ protocolVersion='2024-11-05'; capabilities=@{}; clientInfo=@{ name='codex'; version='1.0' } } } | ConvertTo-Json -Depth 10 -Compress
try {
  $init = Invoke-WebRequest -Uri $base -Method Post -Body $initBody -ContentType 'application/json' -UseBasicParsing -ErrorAction Stop
  "INIT_STATUS=$($init.StatusCode)"
  $sessionId = $init.Headers['Mcp-Session-Id']
  if (-not $sessionId) { $sessionId = $init.Headers['mcp-session-id'] }
  "SESSION_ID=$sessionId"
  "INIT_BODY=$($init.Content)"
  $toolsBody = @{ jsonrpc='2.0'; id=2; method='tools/list'; params=@{} } | ConvertTo-Json -Depth 10 -Compress
  $headers = @{}
  if ($sessionId) { $headers['Mcp-Session-Id'] = $sessionId }
  $tools = Invoke-WebRequest -Uri $base -Method Post -Headers $headers -Body $toolsBody -ContentType 'application/json' -UseBasicParsing -ErrorAction Stop
  "TOOLS_STATUS=$($tools.StatusCode)"
  "TOOLS_BODY=$($tools.Content)"
} catch {
  if ($_.Exception.Response) {
    "POST_STATUS=$([int]$_.Exception.Response.StatusCode)"
    $reader = New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream())
    "POST_BODY=$($reader.ReadToEnd())"
  } else {
    "POST_ERROR=$($_.Exception.Message)"
  }
